function addTwoNumbers(l1, l2) {
    const dummy = new ListNode(0);
    let cur = dummy;
    let p = l1, q = l2;
    let carry = 0;
    while (p !== null || q !== null || carry !== 0) {
        const x = p ? p.val : 0;
        const y = q ? q.val : 0;
        const sum = x + y + carry;
        carry = Math.floor(sum / 10);
        cur.next = new ListNode(sum % 10);
        cur = cur.next;
        if (p) p = p.next;
        if (q) q = q.next;
    }
    return dummy.next;
}

